float between (float x, float hi, float lo)
{return (x<hi)*(x>lo);}
vec2 rotuv (vec2 uvi, float a, float d)
{return multiply(uvi, mat2(cos(a),sin(a),-sin(a),cos(a)))+d;}
vec4 ring (vec2 uvi, float r, float a)
{ float w=r*0.04, ri=r-w, ra=r+w;
float h0, h1, h2, h3; vec2 rs;
vec4 res=0;
h3 = abs(cos(a));
float sw = sin(a)*sign(cos(a));
//Seiten
rs= (uvi + vec2(w*sign(sin(a)), 0.0 )*cos(a))* vec2(1.0 / (sin(a)), 1.0 );
res.x = between (length(rs),ra,ri) *rs.x/ri*cos(a);
//Zylinder, aussen
h0 = uvi.y/ra;
h1 = sqrt (1.0 - h0*h0); //schneller als h1 = cos(asin (h0));
h2 = ra*h1*sw;
res.g = between (uvi.x,w*h3+h2,-w*h3+h2)* (abs(h0)<1) * h1;
//Zylinder, innen
h0 = uvi.y/ri;
h1 = sqrt (1.0 - h0*h0); //schneller als h1 = cos(asin (h0));
h2 = -ri*h1*sw;
res.b = between (uvi.x,w*h3+h2,-w*h3+h2)* (abs(h0)<1) * h1;
//Evtl weglassen weil Fehler kaum sichtbar
res.gb *= (res.r==0)*h3;
res.b  *= (res.g==0);
res.w = between (length(rs),ra,ri)* (uvi.x*sign(cos(a)*sin(a))>-w) || (res.g);
return res;
}
