void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  uv0=(uv-0.5)*uAspect.xy*.6;
uv1=rotuv(uv0,q11,q21);
ret1 = ring (uv1,0.06,q1); //innerster
vec2 uv3=uv1;
uv1=rotuv(uv0,q12,q22);
r2 = ring (uv1,0.08,q2); go
uv1=rotuv(uv0,q13,q23);
r2 = ring (uv1,0.1,q3); go
uv1=rotuv(uv0,q14, q24);
r2 = ring (uv1,0.12, q4); go
uv1=rotuv(uv0,q15, q25);
r2 = ring (uv1,0.14,q5); go
float smask = lum(ret1*vec3( 1.0 , 1.0 ,-1));
float hmask = ret1.w;
float gmask = !(smask==0);
uv1 = (uv-0.5)*uAspect.xy;
vec3 licol = GetBlur1(0.51)*.5+.5;
vec3 light = clamp01(sqrt(0.025/length(uv1)));
light += abs(cross(GetPixel(uv)*vec3( 1.0 , 1.0 , 0.0 ), 1.0 + slow_roam_sin));;
float fla=.1/abs(uv3.x);
light += sat(q19*fla*exp(-256*length(uv3.y)))*sat(1-15*smask)*licol;;
light *= sat(1-3*smask);
ret = mix(ret1.b*ret1.b * 2.0, light, sat(1.0 * sqrt(lum(light))-.1))*licol;
vec2 uvz=(uv-0.5)*0.3+0.5;
ret += sat(0.01/length(uv1-ret1.r-.1))*( vec2(.5) + GetBlur1(uvz).xy)*gmask;
//stars
ret += GetPixel(uv).b * (gmask == 0.0 ? 1.0 : 0.0);
ret += q19*exp(-3*rad)*0.25*(ret1.b+!(ret1.r==0))*licol;
  fragColor = vec4(ret, 1.0);
}

